def get_nth_prime(n):
    primes = []
    num = 2
    while len(primes) < n:
        for p in primes:
            if p * p > num:
                primes.append(num)
                break
            if num % p == 0:
                break
        else:
            primes.append(num)
        num += 1
    return primes[-1]

